prompt --application/shared_components/user_interface/templates/page/theme_111_blank
begin
wwv_flow_imp_shared.create_template(
 p_id=>wwv_flow_imp.id(7468998456261911)
,p_theme_id=>111
,p_name=>'Blank'
,p_static_id=>'blank'
,p_is_popup=>false
,p_javascript_code_onload=>'apex.theme42.initializePage.noSideCol();'
,p_header_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!DOCTYPE html>',
