 p_id=>wwv_flow_imp.id(7404299063050824)
,p_event_id=>wwv_flow_imp.id(7404114923050823)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_name=>'Animate KPI Counters'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'function animateCounter(el) {',
    '  var text = el.textContent.trim();',
    '  var match = text.match(/[\d,]+/);',
    '  if (!match) return;',
    '',
    '  var target = parseInt(match[0].replace(/,/g, ''''), 10);',
    '  if (isNaN(target)) return;',
    '',
    '  var prefix = text.split(match[0])[0];',
    '  var suffix = text.split(match[0])[1] || '''';',
    '  var current = 0;',
    '  var duration = 1000;',
    '  var steps = 40;',
    '  var increment = target / steps;',
    '  var stepTime = duration / steps;',
    '',
    '  var timer = setInterval(function() {',
    '    current += increment;',
    '    if (current >= target) {',
    '      current = target;',
    '      clearInterval(timer);',
    '    }',
    '    el.textContent = prefix + Math.round(current).toLocaleString() + suffix;',
    '  }, stepTime);',
    '}',
    '',
    'var counterEls = document.querySelectorAll(''.a-CardView-mainContent'');',
    '',
    'if (''IntersectionObserver'' in window) {',
    '  var observer = new IntersectionObserver(function(entries) {',
    '    entries.forEach(function(entry) {',
    '      if (entry.isIntersecting) {',
    '        animateCounter(entry.target);',
    '        observer.unobserve(entry.target);',
    '      }',
    '    });',
    '  }, { threshold: 0.4 });',
    '',
    '  counterEls.forEach(function(el) {',
    '    observer.observe(el);',
    '  });',
    '} else {',
    '  // Fallback for very old browsers: just animate immediately',
    '  counterEls.forEach(animateCounter);',
    '}')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20260901211422Z')
,p_updated_on=>wwv_flow_imp.dz('20260901212321Z')
,p_created_by=>'MSOLIMAN'
,p_updated_by=>'MSOLIMAN'
);
end;
