,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'V_MIN NUMBER;',
'V_MAX NUMBER;',
'BEGIN',
'SELECT MIN_SALARY,MAX_SALARY INTO V_MIN,V_MAX',
'FROM OEHR_JOBS',
'WHERE JOB_ID =:P6_JOB_ID;',
'',
'IF :P6_SALARY<V_MIN THEN',
'RETURN ''SALARY LESS THAN MIN MIN SAL IS :''||V_MIN;',
'ELSIF :P6_SALARY>V_MAX THEN',
'RETURN ''SALARY GREATER THAN MAX MAX SAL IS : ''||V_MAX;',
'END IF;',
'END;'))
