wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(7403726167050819)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Notify Manager via n8n'
,p_static_id=>'notify-manager-via-n8n'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_response       CLOB;',
'  l_manager_email  oehr_employees.email%TYPE;',
'  l_manager_name   VARCHAR2(200);',
'  l_job_title      oehr_jobs.job_title%TYPE;',
'  l_body           CLOB;',
'BEGIN',
'  IF :P6_MANAGER_ID IS NOT NULL THEN',
'',
'    SELECT email, first_name || '' '' || last_name',
'    INTO   l_manager_email, l_manager_name',
'    FROM   oehr_employees',
'    WHERE  employee_id = :P6_MANAGER_ID;',
'',
'    SELECT job_title',
'    INTO   l_job_title',
'    FROM   oehr_jobs',
'    WHERE  job_id = :P6_JOB_ID;',
'',
'    -- Build JSON safely with APEX_JSON',
'    apex_json.initialize_clob_output;',
'    apex_json.open_object;',
'    apex_json.write(''employee_name'', :P6_FIRST_NAME || '' '' || :P6_LAST_NAME);',
'    apex_json.write(''employee_email'', :P6_EMAIL);',
'    apex_json.write(''job_title'', l_job_title);',
'    apex_json.write(''manager_name'', l_manager_name);',
'    apex_json.write(''manager_email'', l_manager_email);',
'    apex_json.close_object;',
'    l_body := apex_json.get_clob_output;',
'    apex_json.free_output;',
'',
'    apex_web_service.g_request_headers.delete;',
'    apex_web_service.g_request_headers(1).name  := ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'',
'    l_response := apex_web_service.make_rest_request(',
unistr('      p_url         => ''http://N8N:5678/webhook/new-employee'', -- \0627\0633\062A\062E\062F\0645\0646\0627 \0627\0633\0645 \0627\0644\062D\0627\0648\064A\0629 \0627\0644\062F\0627\062E\0644\064A'),
'      p_http_method => ''POST'',',
'      p_body        => l_body',
'    );',
'  END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(6611003856329020)
,p_internal_uid=>7403726167050819
,p_created_on=>wwv_flow_imp.dz('20260901200007Z')
,p_updated_on=>wwv_flow_imp.dz('20260901202951Z')
,p_created_by=>'MSOLIMAN'
,p_updated_by=>'MSOLIMAN'
);
